function lockBusyControls(){if(!busyControls)return;document.querySelectorAll('#app button,#app input,#app select,#app textarea,dialog button,dialog input,dialog select,dialog textarea,#logout').forEach(n=>{if(!busyControls.has(n))busyControls.set(n,n.disabled);n.disabled=true})}
let management={},ready=false,subscriptions=[],selectedCustomer='',editingSnapshot=null,busy=false,sessionUser='',reportData=null;
