const localDate=t=>{const parts=Object.fromEntries(new Intl.DateTimeFormat('en-US',{timeZone:'Asia/Taipei',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(t?new Date(t):new Date()).map(p=>[p.type,p.value]));return parts.year+'-'+parts.month+'-'+parts.day};
