async function startOrderSession(u){
 sessionSerial++;connected=false;categoryEdit=null;categoryPending=null;for(const id of ['rows','customerList','inventoryList','movementList','reportStats','reportProducts','expenseList','customerMergeHistory'])$(id).textContent='';
 customerSelection=null;mergePreviewState=null;orderDraft=null;$('orderCustomerQuery').value='';$('orderCustomerResults').textContent='';$('orderCustomerSearchStatus').textContent='';$('customerMatchOptions').textContent='';$('mergePreview').textContent='';$('mergeSource').innerHTML='';$('mergeTarget').innerHTML='';
 subscriptions.forEach(([r,f])=>r.off('value',f));subscriptions=[];ready=false;uid='';orders={};products={};management={};selectedCustomer='';customerEditorDirty=false;sessionUser=u?.uid||'';$('customerDetail').innerHTML='';resetExpense();inventoryProductSignature='';categorySignature='';resetShrimp();$('managementError').classList.add('hidden');
 $('auth').classList.toggle('hidden',!!u);$('app').classList.toggle('hidden',!u);$('user').classList.toggle('hidden',!u);
 document.querySelectorAll('dialog[open]').forEach(d=>closeActionDialog(d.id));if(!u)return;
 uid=u.uid;const listenerSerial=sessionSerial;connected=false;const connection=db.ref('.info/connected'),connectionUser=uid;const connectionHandler=s=>{if(uid!==connectionUser||sessionSerial!==listenerSerial)return;connected=s.val()===true;$('syncStatus').textContent=connected?'Firebase 已連線（資料持續同步）':'Firebase 尚未連線，暫停儲存'};connection.on('value',connectionHandler);subscriptions.push([connection,connectionHandler]);op=readOperator()||'家人';$('who').textContent=op;
 const r=rootRef(),userId=uid;const f=s=>{if(uid!==userId||sessionSerial!==listenerSerial)return;try{management=s.val()||{};orders=management.orders||{};products=management.products||{};ready=true;$('syncStatus').textContent=connected?'Firebase 已連線（資料持續同步）':'Firebase 尚未連線，暫停儲存';renderProducts();render();refreshManagement()}catch(e){ready=false;$('syncStatus').textContent='資料顯示失敗，暫停儲存';sessionFailure(e,'Firebase 資料顯示')}};
 r.on('value',f,e=>{if(uid!==userId||sessionSerial!==listenerSerial)return;ready=false;$('syncStatus').textContent='資料同步失敗，暫停儲存';fail(e)});subscriptions.push([r,f]);
}
