 $('orderCustomerResults').innerHTML=shown.map((c,n)=>'<article class="order-customer-result"><b>'+esc(c.name)+' '+esc(c.phoneLast3||'後三碼未記錄')+'</b><p>平台／帳號：'+esc(c.channels.map(x=>x.platform+' '+x.account).join('、'))+'<br>'+c.count+' 次購買 · 累積 '+money(c.total)+'</p><button type="button" data-order-customer="'+n+'">確認使用此客戶</button></article>').join('');
 $('orderCustomerResults').querySelectorAll('[data-order-customer]').forEach(b=>b.onclick=()=>{try{if(!ready||$('oid').value)throw Error('目前無法選擇客戶，請重新開啟新增訂單');const id=shown[+b.dataset.orderCustomer].id,c=customers().find(c=>c.id===id);if(!c)throw Error('客戶資料已更新，請重新搜尋確認');chooseExisting(c,false);if(customerSelection?.kind==='existing'&&customerSelection.id===id){$('orderCustomerQuery').value='';renderOrderCustomerSearch()}}catch(e){fail(e)}});
