// Product removal is archival: stable product IDs and inventory history always remain.
window.removeP=id=>{if(confirm('此操作會下架並保留商品與歷史資料，確定繼續？'))guard(()=>rootRef().child('products/'+id).update({active:false}))};
window.toggleProduct=(id,active)=>guard(()=>rootRef().child('products/'+id).update({active}));
$('productForm').onsubmit=e=>{e.preventDefault();guard(async()=>{const id=$('peid').value||operationId(),name=$('pname').value.trim(),price=Number($('pprice').value);if(!name||!Number.isFinite(price)||price<0)throw Error('請輸入商品名稱及有效價格');if(Object.entries(products).some(([key,p])=>key!==id&&p.name===name))throw Error('已有相同名稱商品');await rootRef().child('products/'+id).update({name,price,...(products[id]?{}:{active:true})});resetProductForm()})};

function refreshManagement(){if(!ready)return;renderCustomers();renderInventory();renderReports();renderExpenses();if($('od').hasAttribute('open')&&!$('oid').value)renderOrderCustomerSearch();lockBusyControls()}
$('panel-customers').innerHTML='<h2>客戶管理</h2><p class="management-help">姓名與手機後三碼只提示候選，須確認後才關聯。跨平台可選用同一客戶；手動合併只建立對照，不改寫歷史訂單。</p><input id="customerSearch" placeholder="搜尋姓名、平台、帳號或電話"><button id="openCustomerMerge" type="button">手動合併客戶</button><div id="customerList"></div><h3>客戶合併紀錄</h3><div id="customerMergeHistory"></div>';
$('customerSearch').oninput=renderCustomers;
function renderCustomers(){const q=$('customerSearch').value.toLowerCase(),all=customers();$('customerList').innerHTML=all.filter(c=>(!q||C.searchCustomers([c],q,management.customers||{}).length||c.channels.some(x=>String(x.platform).toLowerCase().includes(q)))).map(c=>`<article class="card"><b>${esc(c.name)} ${esc(c.phoneLast3||'（後三碼未記錄）')}</b> · ${esc(c.contactType)} ${esc(c.contactAccount)}<p>${c.count} 筆訂單 · 累積 ${money(c.total)}<br>首次 ${dateText(c.first)}<br>最近 ${dateText(c.last)}${c.orders.some(o=>!o.createdAt)?'<br>另含日期不明訂單':''}</p><button data-customer="${esc(c.id)}">查看／編輯</button><button data-newcustomer="${esc(c.id)}">新增訂單</button></article>`).join('')||'<p>沒有符合的客戶</p>';
 $('customerList').querySelectorAll('[data-customer]').forEach(b=>b.onclick=()=>{openCustomer(b.dataset.customer)});$('customerList').querySelectorAll('[data-newcustomer]').forEach(b=>b.onclick=()=>{openOrder();fillCustomer(all.find(c=>c.id===b.dataset.newcustomer))});if(selectedCustomer)customerDetail();renderMergeHistory();}
function customerField(id,label,c){
 const options=id==='contactType'?['Line','IG','FB','711','全家','脆']:id==='delivery'?['','711','全家','宅配','面交']:null;
 const current=String(c[id]||'');
 const values=options&&!options.includes(current)?[...options,current]:options;
 return '<label class="field-label">'+label+(values?'<select name="'+id+'">'+values.map(v=>'<option value="'+esc(v)+'"'+(v===current?' selected':'')+'>'+esc(v||'未指定')+'</option>').join('')+'</select>':id==='notes'?'<textarea name="notes">'+esc(current)+'</textarea>':'<input name="'+id+'" '+(id==='name'?'required ':'')+(id==='phone'?'type="tel" ':id==='phoneLast3'?'type="text" inputmode="numeric" maxlength="3" pattern="[0-9]{3}" ':'')+'value="'+esc(current)+'">')+'</label>';
}
function closeCustomer(){const d=$('customerDialog');if(typeof d.close==='function')d.close();else d.removeAttribute('open');d.classList.remove('dialog-fallback');customerEditorDirty=false;$('customerNotice').textContent=''}
function openCustomer(id){
 try{if(!ready)throw Error('客戶資料尚未完成同步，請稍候再試');if(!customers().some(c=>c.id===id))throw Error('找不到此客戶，請重新整理名單');
 clearErrors();customerEditorDirty=false;selectedCustomer=id;$('customerNotice').textContent='';customerDetail();const d=$('customerDialog');if(!d.open){if(typeof d.showModal==='function')d.showModal();else{d.setAttribute('open','');d.classList.add('dialog-fallback')}}
 }catch(e){fail(e)}
}
$('customerClose').onclick=closeCustomer;
$('customerDialog').addEventListener('cancel',e=>{e.preventDefault();if(!busy)closeCustomer()});
function customerDetail(){
 if(customerEditorDirty)return;const expectedProfile=JSON.parse(JSON.stringify(management.customers?.[selectedCustomer]||null));const c=customers().find(c=>c.id===selectedCustomer);if(!c){$('customerDetail').textContent='找不到此客戶，資料可能已更新，請關閉後重新選擇。';return}
 $('customerDetail').innerHTML='<div class="customer-summary management-grid">'+[['購買次數',c.count+' 次'],['累積消費',money(c.total)],['首次購買',dateText(c.first)],['最近購買',dateText(c.last)]].map(([label,value])=>'<div class="card">'+label+'<strong>'+esc(value)+'</strong></div>').join('')+'</div>'+(c.orders.some(o=>!o.createdAt)?'<p class="management-help">另含建立日期不明的舊訂單，未虛構日期。</p>':'')+'<p class="management-help">聯絡管道：'+esc(c.channels.map(x=>x.platform+' '+x.account).join('、'))+'<br>原始客戶 ID：'+esc(c.sourceIds.join('、'))+'</p><form id="customerEdit"><h3>基本資料</h3>'+[['name','客戶姓名'],['phoneLast3','手機後三碼（舊客戶可留白）'],['phone','電話（選填）'],['contactType','訂購／聯絡平台'],['contactAccount','聯絡帳號'],['delivery','常用取貨方式'],['deliveryDetail','常用取貨地點'],['notes','備註']].map(([id,label])=>customerField(id,label,c)).join('')+'<button type="submit" class="primary">儲存基本資料</button></form><h3>歷史訂單與購買商品</h3><div class="customer-history">'+(c.orders.map(o=>'<p>訂單 '+esc(o.id)+' · '+esc(dateText(o.createdAt))+' · '+money(C.total(o))+' · '+esc(C.items(o).map(i=>(i.productName||'未填商品名')+' × '+(+i.qty||0)+'（贈 '+(+i.gift||0)+'）').join('、'))+'</p>').join('')||'<p>尚無訂單</p>')+'</div>';
 $('customerEdit').oninput=()=>{customerEditorDirty=true;$('customerNotice').textContent='有尚未儲存的修改'};
 $('customerEdit').onsubmit=async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));const saved=await guard(()=>{if(!data.name.trim())throw Error('請填寫客戶姓名');if(data.phoneLast3&&!C.validLast3(data.phoneLast3))throw Error('手機後三碼必須為 3 位數字或留白');return transact(s=>C.updateCustomerProfile(s,c.id,data,expectedProfile,op,firebase.database.ServerValue.TIMESTAMP))});if(saved){customerEditorDirty=false;customerDetail();$('customerNotice').textContent='客戶基本資料已儲存；歷史訂單未變更'}};
}

// Non-destructive merges: aliases only; all original profiles and orders stay in place.
function mergeCustomerCard(c){return '<article class="card"><b>'+esc(c.name)+' '+esc(c.phoneLast3||'後三碼未記錄')+'</b><p>ID：'+esc(c.id)+'<br>電話：'+esc(c.phone||'未填')+'<br>管道：'+esc(c.channels.map(x=>x.platform+' '+x.account).join('、'))+'<br>取貨：'+esc(c.delivery)+' '+esc(c.deliveryDetail)+'<br>備註：'+esc(c.notes)+'<br>'+c.count+' 筆 · 累積 '+money(c.total)+'<br>首次 '+dateText(c.first)+'<br>最近 '+dateText(c.last)+'</p>'+c.orders.map(o=>'<p>訂單 '+esc(o.id)+' · '+dateText(o.createdAt)+' · '+money(C.total(o))+'<br>'+esc(C.items(o).map(i=>i.productName+' × '+i.qty+'（贈 '+(+i.gift||0)+'）').join('、'))+'</p>').join('')+'</article>'}
function invalidateMergePreview(){mergePreviewState=null;$('mergeAcknowledged').checked=false;$('mergeCommit').disabled=true;$('mergePreview').textContent='請重新預覽後確認'}
$('openCustomerMerge').onclick=()=>{try{const all=customers();if(all.length<2)throw Error('至少需要兩位未合併的客戶');const options=all.map(c=>'<option value="'+esc(c.id)+'">'+esc(c.name)+' '+esc(c.phoneLast3||'未記錄')+' · '+esc(c.id)+'</option>').join('');$('mergeSource').innerHTML=options;$('mergeTarget').innerHTML=options;$('mergeTarget').selectedIndex=1;invalidateMergePreview();openActionDialog('customerMergeDialog')}catch(e){fail(e)}};
for(const id of ['mergeSource','mergeTarget'])$(id).onchange=invalidateMergePreview;
$('mergePreviewButton').onclick=()=>{try{invalidateMergePreview();const all=customers(),source=all.find(c=>c.id===$('mergeSource').value),target=all.find(c=>c.id===$('mergeTarget').value);if(!source||!target||source.id===target.id)throw Error('請選擇不同的兩位客戶');mergePreviewState=JSON.parse(JSON.stringify({source,target}));$('mergePreview').innerHTML='<p class="management-error">合併方向：'+esc(source.name)+' '+esc(source.phoneLast3||'未記錄')+' → '+esc(target.name)+' '+esc(target.phoneLast3||'未記錄')+'。保留右方基本資料；不同後三碼也只有在確認同一人後才能手動合併。</p><div class="merge-comparison"><div><h3>併入客戶</h3>'+mergeCustomerCard(source)+'</div><div><h3>保留客戶</h3>'+mergeCustomerCard(target)+'</div></div><p>合計 '+(source.count+target.count)+' 筆 · '+money(source.total+target.total)+'。不會刪除或搬移任何訂單。</p>'}catch(e){fail(e)}};
$('mergeAcknowledged').onchange=()=>{$('mergeCommit').disabled=!mergePreviewState||!$('mergeAcknowledged').checked};
$('mergeCommit').onclick=async()=>{if(!mergePreviewState||!$('mergeAcknowledged').checked){fail(Error('請先預覽並核取確認'));return}const preview=mergePreviewState,operation=operationId();const saved=await guard(()=>transact(s=>C.mergeCustomers(s,preview.source.id,preview.target.id,preview.source,preview.target,operation,op,firebase.database.ServerValue.TIMESTAMP)));if(saved){selectedCustomer=preview.target.id;customerEditorDirty=false;closeActionDialog('customerMergeDialog');renderCustomers();openCustomer(selectedCustomer);$('customerNotice').textContent='合併完成；歷史訂單及原始客戶 ID 均保留，可於合併紀錄解除'}};
$('mergeClose').onclick=()=>closeActionDialog('customerMergeDialog');
function renderMergeHistory(){$('customerMergeHistory').innerHTML=Object.entries(management.customerMergeHistory||{}).sort((a,b)=>(+b[1].date||0)-(+a[1].date||0)).map(([id,h])=>'<article class="card">'+esc(h.sourceSnapshot?.name||h.sourceId)+' → '+esc(h.targetSnapshot?.name||h.targetId)+'<br>'+dateText(h.date)+' · '+esc(h.operator)+' · '+(h.status==='active'?'<button type="button" data-undo-merge="'+esc(id)+'">解除此合併</button>':'已解除 · '+dateText(h.reversedAt))+'</article>').join('')||'<p>尚無合併紀錄</p>';$('customerMergeHistory').querySelectorAll('[data-undo-merge]').forEach(b=>b.onclick=()=>{if(confirm('解除合併只拆開客戶對照，所有訂單保留；合併後新建訂單仍屬於當時選定的保留客戶。確定解除？'))guard(()=>transact(s=>C.undoCustomerMerge(s,b.dataset.undoMerge,op,firebase.database.ServerValue.TIMESTAMP)))})}

$('panel-inventory').innerHTML='<h2>成品庫存管理</h2><p class="management-help">實體庫存於出貨才扣除（含贈品）；未出貨訂單列預訂量。盤點前不顯示可售數。基準前已出貨舊單不補扣；基準後先改回未出貨再出貨才扣除。刪除或調整有扣庫存的訂單會還原差額。負庫存會明確提醒，不阻擋真實出貨紀錄。</p><p id="inventoryBaseline"></p><div id="inventoryList"></div><form id="inventoryInit" class="card"><h3>首次盤點初始化</h3><p>請暫停其他裝置操作，依各商品目前實體數量輸入。這個操作只設定庫存基準，不改寫訂單。</p><div id="inventoryCounts"></div><button class="primary">確認盤點並啟用庫存</button></form><form id="stockForm" class="card"><h3>手動入庫／出庫</h3><label>商品<select id="stockProduct"></select></label><label>異動包數（入庫為正、出庫為負）<input id="stockQty" required type="number" step="1"></label><label>原因<input id="stockReason" required placeholder="製作、破包、報廢、試吃、贈送…"></label><button class="primary">記錄異動</button></form><h3>庫存異動紀錄</h3><div id="movementList"></div>';
let inventoryProductSignature='';
function inventoryProducts(){const p={...products};Object.values(orders).forEach(o=>C.items(o).forEach(i=>{if(i.productId&&!p[i.productId])p[i.productId]={name:i.productName+'（歷史商品）',active:false}}));Object.keys(management.inventory?.stock||{}).forEach(id=>p[id]||=( {name:id+'（歷史商品）',active:false}));return p}
function renderInventory(){const inv=management.inventory||{},all=inventoryProducts(),reserved={};Object.values(orders).filter(o=>!o.shipped).forEach(o=>C.items(o).forEach(i=>{reserved[i.productId]=(reserved[i.productId]||0)+(+i.qty||0)+(+i.gift||0)}));$('inventoryBaseline').textContent=inv.initializedAt?'盤點基準：'+dateText(inv.initializedAt):'尚未初始化：自動扣庫存尚未啟用';$('inventoryInit').classList.toggle('hidden',!!inv.initializedAt);$('stockForm').classList.toggle('hidden',!inv.initializedAt);
 $('inventoryList').innerHTML='<table><thead><tr><th>商品</th><th>實體</th><th>預訂未出貨</th><th>可銷售</th></tr></thead><tbody>'+Object.entries(all).map(([id,p])=>{const counted=inv.initializedAt&&C.hasOwn(inv.stock||{},id),stock=+inv.stock?.[id]||0,held=reserved[id]||0;return `<tr><td>${esc(p.name)}${p.active===false?'（下架）':''}</td><td>${counted?stock:'未盤點'}</td><td>${held}</td><td>${counted?stock-held+(stock-held<0?' ⚠ 不足':''):'—'}</td></tr>`}).join('')+'</tbody></table>';
 const signature=JSON.stringify(all);if(signature!==inventoryProductSignature){inventoryProductSignature=signature;$('inventoryCounts').innerHTML=Object.entries(all).map(([id,p])=>`<label>${esc(p.name)}<input data-stock="${esc(id)}" required type="number" min="0" step="1" placeholder="實際包數"></label>`).join('');$('stockProduct').innerHTML=Object.entries(all).map(([id,p])=>`<option value="${esc(id)}">${esc(p.name)}</option>`).join('')}
 $('movementList').innerHTML=Object.values(management.inventoryMovements||{}).sort((a,b)=>(+b.date||0)-(+a.date||0)).map(m=>`<article class="card">${dateText(m.date)} · ${esc(all[m.productId]?.name||m.productId)} · ${m.quantity>0?'+':''}${m.quantity} 包<br>${esc(m.reason)} · 操作：${esc(m.operator)}${m.orderId?' · 訂單 '+esc(m.orderId):''}</article>`).join('')||'<p>尚無異動</p>';
}
$('inventoryInit').onsubmit=e=>{e.preventDefault();guard(async()=>{const stock={};document.querySelectorAll('[data-stock]').forEach(x=>{const n=Number(x.value);if(!x.value||!Number.isInteger(n)||n<0)throw Error('請完整輸入各商品非負整數庫存');stock[x.dataset.stock]=n});if(!Object.keys(stock).length)throw Error('請先新增商品');if(!confirm('確定以目前輸入的實體庫存建立基準？舊已出貨訂單不會補扣。'))return;const key=operationId();await transact(s=>{if(!s)throw Error('無資料');if(s.inventory?.initializedAt)throw Error('其他裝置已完成初始化，請重新檢查');const allIds=new Set([...Object.keys(s.products||{}),...Object.values(s.orders||{}).flatMap(o=>C.items(o).map(i=>i.productId).filter(Boolean))]);if([...allIds].some(id=>!C.hasOwn(stock,id)))throw Error('商品已更新，請重新確認盤點');const next=JSON.parse(JSON.stringify(s));next.inventory={initializedAt:firebase.database.ServerValue.TIMESTAMP,initializedBy:op,stock,orderLedger:{}};next.inventoryMovements||={};for(const [id,n] of Object.entries(stock))next.inventoryMovements[key+'_'+id]={productId:id,quantity:n,reason:'首次盤點基準（不補扣舊出貨）',operator:op,date:firebase.database.ServerValue.TIMESTAMP};return next})})};
$('stockForm').onsubmit=e=>{e.preventDefault();guard(async()=>{const pid=$('stockProduct').value,qty=Number($('stockQty').value),reason=$('stockReason').value.trim();if(!pid||!Number.isInteger(qty)||!qty||!reason)throw Error('請輸入商品、非零整數數量及原因');const key=operationId();await transact(s=>{if(!s?.inventory?.initializedAt)throw Error('請先初始化庫存');if(s.inventoryMovements?.[key])return s;const n=JSON.parse(JSON.stringify(s));n.inventory.stock||={};n.inventory.stock[pid]=(+n.inventory.stock[pid]||0)+qty;n.inventoryMovements||={};n.inventoryMovements[key]={productId:pid,quantity:qty,reason,operator:op,date:firebase.database.ServerValue.TIMESTAMP};return n});$('stockQty').value='';$('stockReason').value=''})};

// Build-time source fragment used by local integration; not a browser dependency.
function financeMoney(n){return 'NT$ '+Number(n||0).toLocaleString('zh-TW',{minimumFractionDigits:2,maximumFractionDigits:2})}
function downloadCsv(rows,name){const url=URL.createObjectURL(new Blob([C.csvText(rows)],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=name+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
let financeDraft=null,shrimpDraft=null,categorySignature='',categoryEdit=null,categoryPending=null;
const categoryExpected=new Map();
function financeState(){return management.finance||{}}
function categoryMap(){return {...Object.fromEntries(categories.map((name,i)=>['default'+i,{name,status:'active'}])),...(management.expenseCategories||{}),...(financeState().categories||{})}}
async function writeFinance(command){
 const serial=sessionSerial;let problem;
 if(command.kind==='legacy'){
  return transact(s=>{if(!C.equalLegacy(s?.expenses?.[command.id],command.legacySnapshot))throw Error('舊支出已被其他版本修改，請重新開啟');return {...s,finance:C.applyFinance(s.finance,command,op,firebase.database.ServerValue.TIMESTAMP)}});
 }
 const result=await rootRef().child('finance').transaction(f=>{problem=null;try{return C.applyFinance(f,command,op,firebase.database.ServerValue.TIMESTAMP)}catch(e){problem=e;return}},undefined,false);
 if(serial!==sessionSerial)throw Error('登入狀態已變更，請回原帳號確認結果');if(!result.committed)throw problem||Error('財務交易未完成，請重新同步後重試');return result;
}
$('panel-reports').innerHTML=`<h2>營業報表</h2><div class="row"><select id="reportPreset"><option value="day">每日</option><option value="week">本週</option><option value="month" selected>本月</option><option value="year">全年</option><option value="custom">自訂</option></select><input id="reportStart" type="date" aria-label="開始日期"><input id="reportEnd" type="date" aria-label="結束日期"><button id="exportReport">匯出 CSV</button></div><p class="management-help">台灣日期、含首尾。A 商品訂單依建立日；B 商品實收依收款日；C 採購及營運支出依採購日（不論付款）；D 實付支出依付款日（包含以前月份採購）；E 自養蝦估算依製作日。客人配送運費不列商品收入或支出。材料採購與耗用日期可能不同，估算不代表精確會計淨利；自養蝦成本不是現金付款。</p><div id="reportStats" class="management-grid"></div><p id="unknownPayments" role="status"></p><div id="reportProducts"></div>`;
function preset(){const now=localDate(),p=$('reportPreset').value;let start=now,end=now;if(p==='month'){start=now.slice(0,8)+'01';const [y,m]=now.split('-').map(Number);end=localDate(new Date(Date.UTC(y,m,0,4)))}if(p==='year'){start=now.slice(0,4)+'-01-01';end=now.slice(0,4)+'-12-31'}if(p==='week'){const d=new Date(now+'T00:00:00+08:00'),day=new Date(d.getTime()+8*3600000).getUTCDay();start=localDate(d.getTime()-((day+6)%7)*86400000)}if(p!=='custom'){$('reportStart').value=start;$('reportEnd').value=end}renderReports()}
function reportRows(r){return [['訂單數（商品金額可核對）',r.count],['總包數（含贈品）',r.packs],['A 商品訂單金額（建立日）',r.A],['B 商品實收（收款日）',r.B],['所選訂單未付款商品金額',r.unpaid],['所選訂單目前已付款商品金額',r.paid],['已出貨包數（含贈品）',r.shipped],['未出貨包數（含贈品）',r.unshipped],['C 採購及營運支出（採購日）',r.C],['當期採購目前已付款',r.purchasePaid],['當期採購目前未付款',r.purchaseUnpaid],['當期採購付款狀態不明',r.purchaseUnknown],['D 實付採購及營運支出（付款日）',r.D],['E 自養蝦估算成本（非現金／製作日）',r.E],['外購蝦製作成本（僅供查看，不再扣除）',r.externalShrimp],['簡易估算利潤 A−C−E（非精確淨利）',r.estimated],['收款基礎估算比較值 B−D−E（非現金餘額）',r.comparison],['商品現金收支差額 B−D',r.cashBalance],['全期收款日期不明筆數',r.unknownCount],['全期收款日期不明商品金額',r.unknownAmount],['全期商品金額待核對筆數',r.unresolvedOrders],['全期待核對訂單原總額（非商品收入）',r.unresolvedOrderAmount],['全期建立日期不明筆數',r.unknownCreated],['全期支出已付但付款日期不明筆數',r.unknownExpensePayments],['全期支出已付但付款日期不明金額',r.unknownExpensePaymentAmount],['支出日期／金額／覆層衝突待核對筆數',r.invalidExpenses]]}
function renderReports(){if(!$('reportStart').value)return;try{reportData=C.financeReport(orders,management.expenses||{},financeState(),$('reportStart').value,$('reportEnd').value);const r=reportData;$('reportStats').innerHTML=reportRows(r).slice(0,18).map(([k,v],i)=>'<div class="card">'+esc(k)+'<h3>'+(i===0||i===1||i===6||i===7?v:financeMoney(v))+'</h3></div>').join('');$('unknownPayments').textContent=`全期收款日期不明：${r.unknownCount} 筆／${financeMoney(r.unknownAmount)}，不計本期 B。商品金額待核對 ${r.unresolvedOrders} 筆（原總額 ${financeMoney(r.unresolvedOrderAmount)}，不計 A/B）；建立日期不明 ${r.unknownCreated} 筆；支出待核對 ${r.invalidExpenses} 筆；已付支出付款日期不明 ${r.unknownExpensePayments} 筆／${financeMoney(r.unknownExpensePaymentAmount)}。付款狀態不明的舊支出不計 D。`;$('reportProducts').innerHTML='<h3>商品銷售排行（依建立日）</h3><table><tr><th>商品</th><th>付費包數</th><th>贈品</th><th>商品金額</th></tr>'+r.sales.map(x=>'<tr><td>'+esc(x.name)+'</td><td>'+x.qty+'</td><td>'+x.gift+'</td><td>'+financeMoney(x.revenue)+'</td></tr>').join('')+'</table>'}catch(e){reportData=null;$('reportStats').textContent='請輸入有效日期區間：'+e.message;$('unknownPayments').textContent='';$('reportProducts').textContent=''}}
$('reportPreset').onchange=preset;for(const id of ['reportStart','reportEnd'])$(id).onchange=()=>{$('reportPreset').value='custom';renderReports()};
$('exportReport').onclick=()=>{if(reportData)downloadCsv([['快樂蝦農營業報表',$('reportStart').value,$('reportEnd').value],['口徑','A建立日；B收款日；C採購日；D付款日；E製作日／非現金；估算非會計淨利'],...reportRows(reportData),['商品','付費包數','贈品','商品金額'],...reportData.sales.map(x=>[x.name,x.qty,x.gift,x.revenue])],'快樂蝦農報表-'+$('reportStart').value)};
$('panel-expenses').innerHTML=`<h2>料理包支出管理</h2><p class="management-help">不記養殖支出、不扣材料／成品庫存；客人配送運費不記支出。舊支出只讀，編輯／作廢儲存在獨立覆層，每筆僅統計一次。</p><form id="expenseForm" class="card"><h3>採購／營運記帳</h3><input id="expenseId" type="hidden"><label>模式<select id="expenseMode"><option value="simple">簡單記帳</option><option value="detailed">詳細記帳</option></select></label><label>採購／支出日期<input id="expenseDate" type="date" required></label><div id="expenseSimple"><label>項目<input id="expenseTitle"></label><label>分類<select id="expenseCategory"></select></label><label>金額<input id="expenseAmount" inputmode="decimal" placeholder="0.00"></label><label><input id="simpleShrimp" type="checkbox">外購蝦品項</label><label>外購蝦總台斤數（外購蝦必填）<input id="simpleWeight" inputmode="decimal"></label></div><div id="expenseDetailed" class="hidden"><div id="purchaseLines"></div><button type="button" id="addPurchaseLine">新增品項</button></div><label>自己負擔的採購運費<input id="expenseShipping" inputmode="decimal" value="0"></label><label>付款狀態<select id="expensePayment"><option value="" disabled>請確認付款狀態</option><option value="unpaid">未付款</option><option value="paid">全額已付款</option></select></label><label id="expensePaidDateBox">實際付款日期<input id="expensePaidDate" type="date"></label><label>商家<input id="expenseMerchant"></label><label>備註<textarea id="expenseNotes"></textarea></label><p id="expenseTotal" role="status"></p><button class="primary">儲存支出</button><button type="button" id="cancelExpense">取消／新增另一筆</button></form><div class="card"><h3>料理包分類設定</h3><select id="categorySelect"></select><input id="categoryName" placeholder="分類名稱"><button id="addCategory">新增分類</button><button id="renameCategory">修改所選分類</button><button id="toggleCategory">停用／恢復分類</button></div><div class="row"><input id="expenseSearch" placeholder="搜尋項目、分類、商家、備註、操作人員"><input id="expenseStart" type="date" aria-label="支出開始日期"><input id="expenseEnd" type="date" aria-label="支出結束日期"><select id="expenseFilter"><option value="">全部付款狀態</option><option value="paid">已付款</option><option value="unpaid">未付款</option><option value="unknown">付款不明</option></select><label><input id="showVoidExpenses" type="checkbox">顯示作廢</label><button id="exportExpenses">匯出支出 CSV</button></div><div id="expenseList"></div><form id="shrimpForm" class="card"><h3>蝦子製作成本（不連動庫存）</h3><input id="shrimpId" type="hidden"><label>製作日期<input id="shrimpDate" type="date" required></label><label>料理包品項<select id="shrimpProduct" required></select></label><label>來源<select id="shrimpSource"><option value="own">自養蝦（非現金估算）</option><option value="purchased">外購蝦（關聯採購，不再次扣成本）</option></select></label><label>使用台斤數（1 台斤＝600 公克）<input id="shrimpWeight" inputmode="decimal" required></label><label id="shrimpPriceBox">每台斤成本<input id="shrimpPrice" inputmode="decimal"></label><label id="shrimpLinkBox">原蝦子採購品項<select id="shrimpLink"></select></label><label>製作包數（選填）<input id="shrimpPacks" inputmode="numeric"></label><label>備註<textarea id="shrimpNotes"></textarea></label><p id="shrimpTotal" role="status"></p><button class="primary">儲存製作成本</button><button type="button" id="cancelShrimp">取消／新增另一筆</button></form><div class="row"><input id="shrimpSearch" placeholder="搜尋商品、來源、備註"><input id="shrimpStart" type="date" aria-label="製作開始日期"><input id="shrimpEnd" type="date" aria-label="製作結束日期"><label><input id="showVoidShrimp" type="checkbox">顯示作廢</label><button id="exportShrimp">匯出成本 CSV</button></div><div id="shrimpList"></div><h3>財務操作紀錄</h3><div id="financeOperations"></div>`;
function categoryOptions(selected=''){return Object.entries(categoryMap()).filter(([id,c])=>c.status!=='void'||id===selected).map(([id,c])=>'<option value="'+esc(id)+'"'+(id===selected?' selected':'')+'>'+esc(c.name)+(c.status==='void'?'（停用）':'')+'</option>').join('')}
function addPurchaseLine(line={},id=operationId()){const div=document.createElement('div');div.className='purchase-line card';div.dataset.line=id;div.innerHTML='<label>品項<input data-field="name" value="'+esc(line.name||'')+'"></label><label>分類<select data-field="categoryId">'+categoryOptions(line.categoryId)+'</select></label><div class="finance-line-grid"><label>數量<input data-field="quantity" inputmode="decimal" value="'+esc(line.quantityMilli==null?'1':line.quantityMilli/1000)+'"></label><label>單位<input data-field="unit" value="'+esc(line.unit||'')+'"></label><label>單價<input data-field="unitPrice" inputmode="decimal" value="'+esc(line.unitPriceCents==null?'':(line.unitPriceCents/100).toFixed(2))+'"></label></div><label><input data-field="shrimp" type="checkbox" '+(line.shrimp?'checked':'')+'>外購蝦</label><label>外購蝦總台斤數<input data-field="weightCatty" inputmode="decimal" value="'+esc(line.weightMilliCatty?line.weightMilliCatty/1000:'')+'"></label><p data-line-total></p><button type="button" data-remove-line>移除此品項</button>';div.querySelector('[data-remove-line]').onclick=()=>{if(!busy){div.remove();previewExpense()}};$('purchaseLines').append(div)}
function resetExpense(){if(!$('expenseForm'))return;$('expenseForm').reset();$('expenseId').value='';$('expenseDate').value=localDate();$('expensePayment').value='unpaid';$('purchaseLines').textContent='';financeDraft={id:operationId(),operation:operationId(),expected:null,kind:'purchase',completed:false,lineId:'simple'};addPurchaseLine({},'line1');expenseMode();paymentFields()}
function expenseMode(){$('expenseSimple').classList.toggle('hidden',$('expenseMode').value!=='simple');$('expenseDetailed').classList.toggle('hidden',$('expenseMode').value!=='detailed');previewExpense()}
$('expenseMode').onchange=()=>{if($('expenseMode').value==='simple'&&$('purchaseLines').children.length>1&&!confirm('簡單模式只儲存單項金額，不保留本次多品項明細。確認切換？')){$('expenseMode').value='detailed';return}expenseMode()};
function paymentFields(){$('expensePaidDateBox').classList.toggle('hidden',$('expensePayment').value!=='paid');$('expensePaidDate').required=$('expensePayment').value==='paid';previewExpense()}
$('expensePayment').onchange=paymentFields;$('addPurchaseLine').onclick=()=>addPurchaseLine();$('cancelExpense').onclick=()=>{if(!busy)resetExpense()};
function purchaseDraftData(){const mode=$('expenseMode').value,items={};if(mode==='simple')items[financeDraft.lineId]={name:$('expenseTitle').value,categoryId:$('expenseCategory').value,quantity:'1',unit:'筆',unitPrice:$('expenseAmount').value,shrimp:$('simpleShrimp').checked,weightCatty:$('simpleWeight').value};else for(const row of $('purchaseLines').children){const line={};row.querySelectorAll('[data-field]').forEach(x=>line[x.dataset.field]=x.type==='checkbox'?x.checked:x.value);items[row.dataset.line]=line;}return {mode,purchaseDate:$('expenseDate').value,items,shipping:$('expenseShipping').value,paymentStatus:$('expensePayment').value,paidDate:$('expensePaidDate').value,merchant:$('expenseMerchant').value,notes:$('expenseNotes').value}}
function previewExpense(){try{const p=C.financePurchase(purchaseDraftData());$('expenseTotal').textContent='品項 '+financeMoney(p.subtotalCents/100)+' ＋ 自付運費 '+financeMoney(p.shippingCents/100)+' ＝ '+financeMoney(p.totalCents/100)}catch(e){$('expenseTotal').textContent='待完成：'+e.message}for(const row of $('purchaseLines').children){try{const q=row.querySelector('[data-field="quantity"]').value,p=row.querySelector('[data-field="unitPrice"]').value;row.querySelector('[data-line-total]').textContent='小計 '+financeMoney(C.roundedProduct(C.scaled(q,3),C.scaled(p,2))/100)}catch(_){row.querySelector('[data-line-total]').textContent='小計待填'}}}
$('expenseForm').addEventListener('input',previewExpense);
$('expenseForm').onsubmit=e=>{e.preventDefault();if(financeDraft?.completed){fail(Error('此表單已儲存；請從清單編輯，或按取消／新增另一筆'));return}guard(async()=>{const draft=financeDraft;if(!draft)throw Error('請重新開啟記帳表單');const data=purchaseDraftData();C.financePurchase(data);await writeFinance({...draft,data,legacySnapshot:draft.legacySnapshot});draft.completed=true;$('expenseTotal').textContent='已儲存；再次記帳請按「取消／新增另一筆」，避免重複提交。'})};
function editExpense(entry){if(busy)return;if(entry.source==='legacy'&&!management.expenses?.[entry.sourceId]){fail(Error('原舊支出已由其他版本移除，請先人工核對；本系統不重建或搬移原資料'));return}if(entry.source==='legacy'&&financeState().legacyExpenseOverrides?.[entry.sourceId]&&!C.equalLegacy(management.expenses[entry.sourceId],financeState().legacyExpenseOverrides[entry.sourceId].legacySnapshot)){fail(Error('原舊支出已被其他版本修改，覆層暫停統計；請先人工核對原紀錄與操作歷史'));return}resetExpense();const isLegacy=entry.source==='legacy',old=isLegacy?financeState().legacyExpenseOverrides?.[entry.sourceId]||null:financeState().purchases?.[entry.sourceId]||null,p=entry;
 financeDraft={id:entry.sourceId,operation:operationId(),expected:old?JSON.parse(JSON.stringify(old)):null,kind:isLegacy?'legacy':'purchase',legacySnapshot:isLegacy?JSON.parse(JSON.stringify(management.expenses[entry.sourceId])):undefined,completed:false,lineId:Object.keys(p.items||{})[0]||'simple'};$('expenseId').value=entry.id;$('expenseDate').value=p.purchaseDate||'';$('expenseMode').value=p.mode||'simple';const line=Object.values(p.items||{})[0]||{};$('expenseTitle').value=line.name||p.title||'';$('expenseCategory').innerHTML=categoryOptions(line.categoryId);$('expenseCategory').value=line.categoryId||'default0';$('expenseAmount').value=(p.subtotalCents??p.totalCents??0)/100;$('simpleShrimp').checked=!!line.shrimp;$('simpleWeight').value=line.weightMilliCatty?line.weightMilliCatty/1000:'';$('purchaseLines').textContent='';for(const [id,l] of Object.entries(p.items||{}))addPurchaseLine(l,id);$('expenseShipping').value=(p.shippingCents||0)/100;$('expensePayment').value=p.payment?.status==='paid'?'paid':p.payment?.status==='unpaid'?'unpaid':'';$('expensePaidDate').value=p.payment?.paidDate||'';$('expenseMerchant').value=p.merchant||'';$('expenseNotes').value=p.notes||'';expenseMode();paymentFields();if(p.payment?.status==='unknown')$('expenseTotal').textContent='舊支出付款狀態不明，儲存前請人工確認未付／全付；不會自動判定。';$('expenseForm').scrollIntoView({block:'start'})}
function visibleExpenses(){const q=$('expenseSearch').value.toLowerCase(),start=$('expenseStart').value,end=$('expenseEnd').value,pay=$('expenseFilter').value;return C.financeEntries(management.expenses||{},financeState()).filter(p=>(p.status!=='void'||$('showVoidExpenses').checked)&&(!start||p.purchaseDate>=start)&&(!end||p.purchaseDate<=end)&&(!pay||p.payment?.status===pay)&&[p.merchant,p.notes,p.operator,...Object.values(p.items||{}).flatMap(l=>[l.name,categoryMap()[l.categoryId]?.name,l.category])].join(' ').toLowerCase().includes(q)).sort((a,b)=>String(b.purchaseDate).localeCompare(String(a.purchaseDate)))}
async function setFinanceStatus(kind,id,old,status,legacySnapshot){if(!confirm(status==='void'?'確認作廢？原資料與歷史保留，報表排除此筆。':'確認復原？將重新納入統計。'))return;await guard(()=>writeFinance({kind,id,expected:old,action:'status',status,operation:operationId(),legacySnapshot}))}
function renderExpenses(){const cats=categoryMap(),signature=JSON.stringify(cats);if(signature!==categorySignature){categorySignature=signature;for(const id of ['expenseCategory','categorySelect']){const v=$(id).value;$(id).innerHTML=categoryOptions(v);if(cats[v])$(id).value=v}categoryExpected.clear();for(const [id] of Object.entries(cats))categoryExpected.set(id,financeState().categories?.[id]?JSON.parse(JSON.stringify(financeState().categories[id])):null);for(const row of $('purchaseLines').children){const select=row.querySelector('[data-field="categoryId"]'),v=select.value;select.innerHTML=categoryOptions(v)}}
 const entries=visibleExpenses();$('expenseList').innerHTML=entries.map((p,n)=>'<article class="card"><b>'+esc(Object.values(p.items||{}).map(l=>l.name).join('、'))+' · '+(p.totalCents===null?'金額待核對':financeMoney(p.totalCents/100))+'</b><p>'+esc(p.purchaseDate||'日期不明')+' · '+(p.source==='legacy'?'舊支出（原資料只讀）':'新版記帳')+' · '+esc(({paid:'已付款',unpaid:'未付款',unknown:'付款狀態不明'})[p.payment?.status]||'付款不明')+' '+esc(p.payment?.paidDate||'')+'<br>'+esc(p.merchant||'')+' · '+esc(p.operator||'')+'<br>'+esc(p.notes||'')+(p.status==='void'?'<br>已作廢':'')+'</p><button data-expense="'+n+'">編輯'+(p.source==='legacy'?'覆層':'')+'</button><button data-delexpense="'+n+'">'+(p.status==='void'?'復原':'作廢')+'</button></article>').join('')||'<p>沒有符合的支出</p>';
 $('expenseList').querySelectorAll('[data-expense]').forEach(b=>b.onclick=()=>editExpense(entries[+b.dataset.expense]));$('expenseList').querySelectorAll('[data-delexpense]').forEach(b=>b.onclick=()=>{const p=entries[+b.dataset.delexpense],kind=p.source==='legacy'?'legacy':'purchase',old=kind==='legacy'?financeState().legacyExpenseOverrides?.[p.sourceId]||null:financeState().purchases[p.sourceId];if(kind==='legacy'&&!old){fail(Error('舊支出請先編輯確認資料並儲存覆層，再作廢；原支出保持唯讀。'));return}setFinanceStatus(kind,p.sourceId,old,p.status==='void'?'active':'void',p.source==='legacy'?management.expenses[p.sourceId]:undefined)});renderShrimp();renderFinanceOperations()}
for(const id of ['expenseSearch','expenseStart','expenseEnd','expenseFilter','showVoidExpenses'])$(id).oninput=renderExpenses;
$('exportExpenses').onclick=()=>downloadCsv([['支出日期','來源 ID','品項','分類','數量','單位','單價','品項小計','自付運費（每採購首列）','採購總額（首列）','付款狀態','付款日期','商家','備註','狀態'],...visibleExpenses().flatMap(p=>Object.values(p.items||{}).map((l,i)=>[p.purchaseDate,p.id,l.name,categoryMap()[l.categoryId]?.name||l.category,l.quantityMilli==null?'':l.quantityMilli/1000,l.unit,l.unitPriceCents==null?'':l.unitPriceCents/100,l.subtotalCents==null?'待核對':l.subtotalCents/100,i?'':p.shippingCents/100,i?'':p.totalCents==null?'待核對':p.totalCents/100,p.payment?.status,p.payment?.paidDate,p.merchant,p.notes,p.status]))],'快樂蝦農料理包支出');
$('categoryName').addEventListener('input',()=>{const id=$('categorySelect').value;if(categoryEdit?.id!==id)categoryEdit={id,expected:categoryExpected.get(id)||null}});
$('categorySelect').onchange=()=>{const id=$('categorySelect').value;categoryEdit={id,expected:categoryExpected.get(id)||null}};
async function saveCategory(add=false,toggle=false){const id=add?(categoryPending?.id||operationId()):$('categorySelect').value,expected=add?null:categoryEdit?.id===id?categoryEdit.expected:categoryExpected.get(id)||null,name=toggle?categoryMap()[id]?.name:$('categoryName').value.trim();const data={name,status:toggle&&categoryMap()[id]?.status!=='void'?'void':'active'};if(add){if(categoryPending&&!C.equalLegacy(categoryPending.data,data)){fail(Error('上次新增分類尚未確認，請先用原名稱重試並確認清單'));return}categoryPending||={id,operation:operationId(),data};}await guard(async()=>{await writeFinance({kind:'category',id,expected,operation:add?categoryPending.operation:operationId(),data});$('categoryName').value='';categoryEdit=null;categoryPending=null})}
$('addCategory').onclick=()=>saveCategory(true);$('renameCategory').onclick=()=>saveCategory();$('toggleCategory').onclick=()=>saveCategory(false,true);
function resetShrimp(){if(!$('shrimpForm'))return;$('shrimpForm').reset();$('shrimpId').value='';$('shrimpDate').value=localDate();shrimpDraft={id:operationId(),operation:operationId(),expected:null,kind:'shrimp',completed:false};shrimpFields()}
function shrimpFields(){$('shrimpPriceBox').classList.toggle('hidden',$('shrimpSource').value!=='own');$('shrimpLinkBox').classList.toggle('hidden',$('shrimpSource').value!=='purchased');previewShrimp()}
function shrimpData(){const link=$('shrimpLink').value.split('/'),productId=$('shrimpProduct').value;return {date:$('shrimpDate').value,productId,productName:inventoryProducts()[productId]?.name||shrimpDraft?.expected?.productName||'',sourceType:$('shrimpSource').value,weightCatty:$('shrimpWeight').value,unitCost:$('shrimpPrice').value,purchaseId:link[0],lineId:link[1],packs:$('shrimpPacks').value,notes:$('shrimpNotes').value}}
function previewShrimp(){try{const s=C.financeShrimp(shrimpData(),financeState());$('shrimpTotal').textContent=financeMoney(s.estimatedCostCents/100)+(s.sourceType==='own'?'（非現金估算）':'（已含採購，不再次扣除）')}catch(e){$('shrimpTotal').textContent='待完成：'+e.message}}
$('shrimpSource').onchange=shrimpFields;$('shrimpForm').addEventListener('input',previewShrimp);$('cancelShrimp').onclick=()=>{if(!busy)resetShrimp()};
$('shrimpForm').onsubmit=e=>{e.preventDefault();if(shrimpDraft?.completed){fail(Error('此表單已儲存；請從清單編輯，或按取消／新增另一筆'));return}guard(async()=>{const draft=shrimpDraft;await writeFinance({...draft,data:shrimpData()});draft.completed=true;$('shrimpTotal').textContent='已儲存；新增下一筆請按「取消／新增另一筆」。'})};
function visibleShrimp(){const q=$('shrimpSearch').value.toLowerCase();return Object.entries(financeState().shrimpCosts||{}).filter(([,s])=>(s.status!=='void'||$('showVoidShrimp').checked)&&(!$('shrimpStart').value||s.date>=$('shrimpStart').value)&&(!$('shrimpEnd').value||s.date<=$('shrimpEnd').value)&&[s.productName,s.notes,s.sourceType==='own'?'自養蝦':'外購蝦'].join(' ').toLowerCase().includes(q)).sort((a,b)=>b[1].date.localeCompare(a[1].date))}
function renderShrimp(){const product=$('shrimpProduct').value,productsAll=inventoryProducts();if(shrimpDraft?.expected&&!productsAll[shrimpDraft.expected.productId])productsAll[shrimpDraft.expected.productId]={name:shrimpDraft.expected.productName};$('shrimpProduct').innerHTML=Object.entries(productsAll).map(([id,p])=>'<option value="'+esc(id)+'">'+esc(p.name)+'</option>').join('');if(productsAll[product])$('shrimpProduct').value=product;const link=$('shrimpLink').value;$('shrimpLink').innerHTML='<option value="">請選擇原蝦子採購</option>'+Object.entries(financeState().purchases||{}).filter(([,p])=>p.status==='active').flatMap(([id,p])=>Object.entries(p.items).filter(([,l])=>l.shrimp).map(([lid,l])=>'<option value="'+esc(id+'/'+lid)+'">'+esc(p.purchaseDate+' '+l.name)+' · '+l.weightMilliCatty/1000+' 台斤</option>')).join('');$('shrimpLink').value=link;
 const list=visibleShrimp();$('shrimpList').innerHTML=list.map(([id,s],n)=>'<article class="card"><b>'+esc(s.productName)+' · '+financeMoney(s.estimatedCostCents/100)+'</b><p>'+esc(s.date)+' · '+(s.sourceType==='own'?'自養蝦／非現金':'外購蝦／不重扣')+' · '+s.weightMilliCatty/1000+' 台斤 · '+esc(s.notes||'')+(s.status==='void'?' · 已作廢':'')+'</p><button data-shrimp-edit="'+n+'">編輯</button><button data-shrimp-status="'+n+'">'+(s.status==='void'?'復原':'作廢')+'</button></article>').join('')||'<p>尚無符合的製作成本</p>';
 $('shrimpList').querySelectorAll('[data-shrimp-edit]').forEach(b=>b.onclick=()=>{if(busy)return;const [id,s]=list[+b.dataset.shrimpEdit];shrimpDraft={id,operation:operationId(),kind:'shrimp',expected:JSON.parse(JSON.stringify(s)),completed:false};$('shrimpId').value=id;$('shrimpDate').value=s.date;$('shrimpProduct').value=s.productId;$('shrimpSource').value=s.sourceType;$('shrimpWeight').value=s.weightMilliCatty/1000;$('shrimpPrice').value=s.unitCostCents/100;$('shrimpLink').value=s.purchaseId+'/'+s.lineId;$('shrimpPacks').value=s.packs||'';$('shrimpNotes').value=s.notes||'';shrimpFields();$('shrimpForm').scrollIntoView({block:'start'})});$('shrimpList').querySelectorAll('[data-shrimp-status]').forEach(b=>b.onclick=()=>{const [id,s]=list[+b.dataset.shrimpStatus];setFinanceStatus('shrimp',id,s,s.status==='void'?'active':'void')})}
for(const id of ['shrimpSearch','shrimpStart','shrimpEnd','showVoidShrimp'])$(id).oninput=renderShrimp;
$('exportShrimp').onclick=()=>downloadCsv([['製作日期','商品','來源','台斤（600g）','每台斤成本','估算成本','製作包數','採購 ID','採購品項 ID','備註','狀態'],...visibleShrimp().map(([id,s])=>[s.date,s.productName,s.sourceType,s.weightMilliCatty/1000,s.unitCostCents/100,s.estimatedCostCents/100,s.packs||'',s.purchaseId,s.lineId,s.notes,s.status])],'快樂蝦農蝦子製作成本');
function renderFinanceOperations(){$('financeOperations').innerHTML=Object.values(financeState().operations||{}).sort((a,b)=>(+b.date||0)-(+a.date||0)).slice(0,100).map(h=>'<article class="card">'+esc(dateText(h.date))+' · '+esc(h.operator)+' · '+esc(({purchase:'採購',shrimp:'蝦子成本',category:'分類',legacy:'舊支出覆層'})[h.kind]||h.kind)+' · '+esc(h.id)+' · '+esc(h.action)+'<details><summary>修訂前後資料</summary><pre>'+esc(JSON.stringify({before:h.before,after:h.after},null,2))+'</pre></details></article>').join('')||'<p>尚無財務操作</p>'}
resetExpense();resetShrimp();preset();

function sessionFailure(e,stage){window.reportScriptFailure(e,{file:'management.js',stage});fail(e)}
window.addEventListener('unhandledrejection',e=>sessionFailure(e.reason,'非同步操作'));
// Catch application callback errors here, before the cross-origin SDK can rethrow them.
auth.onAuthStateChanged(u=>{startOrderSession(u).catch(e=>sessionFailure(e,'Firebase 登入狀態初始化'))},e=>sessionFailure(e,'Firebase Authentication'));


for(const dialog of document.querySelectorAll('dialog'))dialog.addEventListener('cancel',e=>{if(busy)e.preventDefault()});
function fitDialogsToViewport(){const v=window.visualViewport;document.documentElement.style.setProperty('--shrimp-dialog-height',Math.max(80,(v?v.height:window.innerHeight)-24)+'px');document.documentElement.style.setProperty('--shrimp-dialog-top',(Math.max(0,v?v.offsetTop:0)+12)+'px')}
window.addEventListener('resize',fitDialogsToViewport);if(window.visualViewport){window.visualViewport.addEventListener('resize',fitDialogsToViewport);window.visualViewport.addEventListener('scroll',fitDialogsToViewport)}fitDialogsToViewport();
